function main() {
    // write code here:
    var m=Number(stdin[0]);
    var n=1;
    for(var i=1;i<=m;i++){
        n+=4*(i-1);
    }
    console.log(n);
}

const readline = require('readline');
const rl = readline.createInterface({input: process.stdin});
var stdin = [];
rl.on('line', function (line) {stdin.push(line);});
rl.on('close', main);
